module Top;
 typedef enum logic [3:0] {LOW = 4'd1, MID = 4'd4, HIGH = 4'd9} Level;
 class Holder;
  function int take(int v);
   Level l;
   if ($cast(l, v)) return int'(l);
   return -1;
  endfunction
 endclass
 function automatic int take(int v);
  Level l;
  if ($cast(l, v)) return int'(l);
  return -1;
 endfunction
 Level m;
 int v = 3;
 Holder h;
 initial begin
  h = new;
  $display("[%0d %0d %0d %0d]", h.take(4), h.take(3), take(3), $cast(m, v));
 end
endmodule
module Wrapped;
 Top dut();
endmodule
